import * as React from "react";
import Head from "next/head";
import type { GetStaticProps } from "next";
import { PageParamsProvider as PageParamsProvider__ } from "@plasmicapp/react-web/lib/host";
import { extractPlasmicQueryData } from "@plasmicapp/react-web/lib/prepass";
import GlobalContextsProvider from "../components/plasmic/toothmonster/PlasmicGlobalContextsProvider";

import { PlasmicHomepage } from "../components/plasmic/toothmonster/PlasmicHomepage";
import { useRouter } from "next/router";
import { PlasmicQueryDataProvider } from "@plasmicapp/react-web/lib/query";
import { EyeLoader } from "@/components/plasmic-components/EyeLoader";

// The hero image is the Largest Contentful Paint element. Preloading it lets
// the browser start the download from the <head>, before the page's JS and CSS
// have told it the image exists.
const HERO_IMAGE = "/plasmic/toothmonster/images/toothcontactGif.gif";

interface HomepageProps {
  queryCache?: Record<string, unknown>;
}

// GlobalContextsProvider supplies CmsCredentialsProvider. Without it the
// CmsQueryRepeater on this page has no credentials and renders its empty
// state, so the homepage shows no CMS content at all. Plasmic adds this
// wrapper only to the page files it generates; this one was generated
// without it, and since the file is ours a later sync will not add it.
// It belongs here rather than in _app.tsx: the [slug].tsx pages already
// wrap themselves, and nesting the provider crashes the production build.
//
// The same tree is rendered by getStaticProps (to collect the CMS query
// results) and by the page, so the server HTML already contains the case
// studies instead of Shimmer placeholders that are swapped out after a
// client-side fetch.
function HomepageTree({
  route,
  query,
  splashDone,
}: {
  route?: string;
  query?: Record<string, string | string[] | undefined>;
  splashDone: boolean;
}) {
  return (
    <GlobalContextsProvider>
      <PageParamsProvider__ route={route} params={query} query={query}>
        <EyeLoader hidden={splashDone} fadeMs={200} />
        <PlasmicHomepage />
      </PageParamsProvider__>
    </GlobalContextsProvider>
  );
}

function Homepage({ queryCache }: HomepageProps) {
  const router = useRouter();
  // The splash is rendered on the server, so it is part of the very first
  // HTML the browser paints, before React has hydrated. It hides as soon as
  // the page is interactive: hydration (this effect) plus one frame so the
  // hydrated page has painted underneath it. No minimum hold.
  const [splashDone, setSplashDone] = React.useState(false);
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setSplashDone(true));
    return () => cancelAnimationFrame(frame);
  }, []);

  return (
    <>
      <Head>
        <link rel="preload" as="image" href={HERO_IMAGE} fetchPriority="high" />
      </Head>
      <PlasmicQueryDataProvider prefetchedCache={queryCache}>
        <HomepageTree route={router?.pathname} query={router?.query} splashDone={splashDone} />
      </PlasmicQueryDataProvider>
    </>
  );
}

export default Homepage;

export const getStaticProps: GetStaticProps<HomepageProps> = async () => {
  const queryCache = await extractPlasmicQueryData(
    <PlasmicQueryDataProvider>
      <HomepageTree route="/" query={{}} splashDone={false} />
    </PlasmicQueryDataProvider>
  );
  // Rebuilt in the background at most once a minute, so a CMS edit shows up
  // without a redeploy.
  return { props: { queryCache }, revalidate: 60 };
};
